/**
 * 获取字符字模数据
 * @param ch 字符（ASCII 0x20 ~ 0x7E）
 * @return 字模数据指针，如果字符不在范围内返回 NULL
 */
const unsigned char* Font_Get16x32(char ch)
{
    if(ch < FONT_ASCII_FIRST || ch > FONT_ASCII_LAST)
        return NULL;
    return Font_ASCII_16x32[ch - FONT_ASCII_FIRST];
}

